-- Todos os dados são sintéticos; este arquivo roda nos modos strict e legacy do harness local.
SELECT set_config('t.arc_cancelled', t.mk_order('10000000-0000-0000-0000-00000000000a','CANCELLED')::text, false);
SELECT set_config('t.arc_delivered', t.mk_order('10000000-0000-0000-0000-00000000000a','DELIVERED','PICKUP','CASH','PAID','f0000000-0000-0000-0000-0000000000a7')::text, false);
SELECT set_config('t.arc_active', t.mk_order('10000000-0000-0000-0000-00000000000a','PREPARING')::text, false);
SELECT set_config('t.arc_b', t.mk_order('10000000-0000-0000-0000-00000000000b','CANCELLED')::text, false);
SELECT set_config('t.arc_row', (t.order_row(current_setting('t.arc_delivered')::uuid) - ARRAY['archived_at','archived_by','updated_at'])::text, false);
SELECT set_config('t.arc_money', (SELECT jsonb_build_object('count', count(*), 'revenue', sum(total_amount))::text FROM public.orders WHERE status='DELIVERED'), false);
SELECT set_config('t.arc_customer', (SELECT to_jsonb(c)::text FROM public.customers c WHERE id='f0000000-0000-0000-0000-0000000000a7'), false);
SELECT t.ok((SELECT prosecdef AND proconfig @> ARRAY['search_path=""'] FROM pg_proc WHERE oid='public.archive_orders(uuid[],boolean)'::regprocedure), 'RPC SECURITY DEFINER e search_path vazio');
SELECT t.ok(NOT has_function_privilege('anon','public.archive_orders(uuid[],boolean)','EXECUTE'), 'anon sem EXECUTE');
SELECT t.ok(NOT has_table_privilege('authenticated','public.orders','DELETE'), 'sem privilégio DELETE');

SET ROLE anon;
SELECT t.throws($$SELECT public.archive_orders(ARRAY[]::uuid[],true)$$, 'permission denied', 'anon não chama RPC');
SET ROLE authenticated;
SELECT t.login(NULL);
SELECT t.throws($$SELECT public.archive_orders(ARRAY[]::uuid[],true)$$, 'AUTH_REQUIRED', 'sem identidade não arquiva');
SELECT t.login('a0000000-0000-0000-0000-000000000003');
SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L]::uuid[],true)$$, current_setting('t.arc_cancelled')), 'ORDER_NOT_FOUND', 'OPERATOR não arquiva');
SELECT t.login('a0000000-0000-0000-0000-000000000004');
SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L]::uuid[],true)$$, current_setting('t.arc_cancelled')), 'ORDER_NOT_FOUND', 'CASHIER não arquiva');
SELECT t.login('b0000000-0000-0000-0000-000000000001');
SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L]::uuid[],true)$$, current_setting('t.arc_cancelled')), 'ORDER_NOT_FOUND', 'OWNER B não arquiva pedido A');
SELECT t.login('a0000000-0000-0000-0000-000000000001');
SELECT set_config('t.arc_reports', public.get_tenant_reports_summary('10000000-0000-0000-0000-00000000000a', '2000-01-01', '2100-01-01')::text, false);
SELECT set_config('t.arc_crm_history', public.crm_get_customer_orders('10000000-0000-0000-0000-00000000000a','f0000000-0000-0000-0000-0000000000a7')::text, false);

SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L]::uuid[],true)$$, current_setting('t.arc_b')), 'ORDER_NOT_FOUND', 'OWNER A não arquiva pedido B');
SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L,%L]::uuid[],true)$$, current_setting('t.arc_cancelled'), current_setting('t.arc_active')), 'ORDER_ARCHIVE_STATUS', 'lote com status ativo rejeitado');
SELECT t.ok(t.order_row(current_setting('t.arc_cancelled')::uuid)->>'archived_at' IS NULL, 'lote rejeitado não arquiva parcialmente');
SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L,%L]::uuid[],true)$$, current_setting('t.arc_cancelled'), current_setting('t.arc_b')), 'ORDER_NOT_FOUND', 'lote entre lojas rejeitado');
SELECT t.throws($$SELECT public.archive_orders(ARRAY['00000000-0000-0000-0000-000000000000']::uuid[],true)$$, 'ORDER_NOT_FOUND', 'id inexistente rejeitado');
SELECT t.throws($$SELECT public.archive_orders(ARRAY[]::uuid[],true)$$, 'INVALID_ORDER_IDS', 'lote vazio rejeitado');
SELECT t.throws($$SELECT public.archive_orders(ARRAY[NULL]::uuid[],true)$$, 'INVALID_ORDER_IDS', 'id null rejeitado');
SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L]::uuid[],NULL)$$, current_setting('t.arc_cancelled')), 'INVALID_ORDER_IDS', 'ação null rejeitada');
SELECT t.throws(format($$UPDATE public.orders SET archived_at=now(),archived_by=auth.uid() WHERE id=%L$$, current_setting('t.arc_cancelled')), 'permission denied', 'UPDATE direto negado');
SELECT t.is(public.archive_orders(ARRAY[current_setting('t.arc_cancelled')::uuid,current_setting('t.arc_delivered')::uuid],true), 2, 'OWNER arquiva cancelado e entregue');
SELECT t.ok((t.order_row(current_setting('t.arc_delivered')::uuid)->>'archived_at') IS NOT NULL, 'archived_at persistido');
SELECT t.is(t.order_row(current_setting('t.arc_delivered')::uuid)->>'archived_by','a0000000-0000-0000-0000-000000000001', 'autoria persistida');
SELECT t.is(public.archive_orders(ARRAY[current_setting('t.arc_delivered')::uuid,current_setting('t.arc_delivered')::uuid],true), 0, 'repetição e IDs duplicados não mudam auditoria');
SELECT t.is((t.order_row(current_setting('t.arc_delivered')::uuid) - ARRAY['archived_at','archived_by','updated_at'])::text,current_setting('t.arc_row'),'dados do pedido intactos');
SELECT t.ok(EXISTS(SELECT 1 FROM public.orders WHERE id=current_setting('t.arc_delivered')::uuid), 'pedido arquivado continua visível sob RLS');
SELECT t.throws(format($$DELETE FROM public.orders WHERE id=%L$$, current_setting('t.arc_delivered')), 'permission denied', 'OWNER não exclui pedido arquivado');
SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L]::uuid[],false)$$, current_setting('t.arc_active')), 'ORDER_ARCHIVE_STATUS', 'status ativo também rejeitado no desarquivamento');

SELECT t.is(public.get_tenant_reports_summary('10000000-0000-0000-0000-00000000000a', '2000-01-01', '2100-01-01')::text, current_setting('t.arc_reports'), 'RPC de relatórios inclui arquivados normalmente');
SELECT t.is(public.crm_get_customer_orders('10000000-0000-0000-0000-00000000000a','f0000000-0000-0000-0000-0000000000a7')::text, current_setting('t.arc_crm_history'), 'histórico CRM preservado');
SELECT t.login('a0000000-0000-0000-0000-000000000007');
SELECT t.is(public.get_customer_order_by_id(current_setting('t.arc_delivered')::uuid)->>'id', current_setting('t.arc_delivered'), 'cliente consulta seu pedido arquivado');
SELECT t.login('b0000000-0000-0000-0000-000000000001');
SELECT t.ok(NOT EXISTS(SELECT 1 FROM public.orders WHERE id=current_setting('t.arc_delivered')::uuid), 'arquivado A não visível em B');
SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L]::uuid[],false)$$, current_setting('t.arc_delivered')), 'ORDER_NOT_FOUND', 'OWNER B não desarquiva A');
RESET ROLE;
SELECT t.is((SELECT jsonb_build_object('count', count(*), 'revenue', sum(total_amount))::text FROM public.orders WHERE status='DELIVERED'),current_setting('t.arc_money'),'contagem e faturamento preservados');
SELECT t.is((SELECT to_jsonb(c)::text FROM public.customers c WHERE id='f0000000-0000-0000-0000-0000000000a7'),current_setting('t.arc_customer'),'métricas CRM intactas');
SELECT t.ok(EXISTS(SELECT 1 FROM public.audit_logs WHERE resource_id=current_setting('t.arc_delivered') AND action='ORDER_ARCHIVED'), 'auditoria de arquivamento');
SELECT t.throws(format($$DELETE FROM public.orders WHERE id=%L$$, current_setting('t.arc_delivered')), 'ORDER_DELETE_FORBIDDEN', 'trigger impede exclusão até por operação de sistema');
SELECT t.throws(format($$UPDATE public.orders SET total_amount=1 WHERE id=%L$$, current_setting('t.arc_delivered')), 'ORDER_FIELD_IMMUTABLE', 'campos financeiros continuam imutáveis');
UPDATE public.tenants SET status='SUSPENDED' WHERE id='10000000-0000-0000-0000-00000000000a';
SET ROLE authenticated;
SELECT t.login('a0000000-0000-0000-0000-000000000001');
SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L]::uuid[],false)$$, current_setting('t.arc_delivered')), 'ORDER_NOT_FOUND', 'loja inativa não desarquiva');
RESET ROLE;
UPDATE public.tenants SET status='ACTIVE' WHERE id='10000000-0000-0000-0000-00000000000a';

-- Membro inativo perde acesso, mesmo mantendo OWNER/MANAGER no role_id.
UPDATE public.tenant_users SET status='SUSPENDED' WHERE user_id='a0000000-0000-0000-0000-000000000002';
SET ROLE authenticated;
SELECT t.login('a0000000-0000-0000-0000-000000000002');
SELECT t.throws(format($$SELECT public.archive_orders(ARRAY[%L]::uuid[],false)$$, current_setting('t.arc_delivered')), 'ORDER_NOT_FOUND', 'MANAGER inativo não desarquiva');
RESET ROLE;
UPDATE public.tenant_users SET status='ACTIVE' WHERE user_id='a0000000-0000-0000-0000-000000000002';
SET ROLE authenticated;
SELECT t.is(public.archive_orders(ARRAY[current_setting('t.arc_delivered')::uuid],false), 1, 'MANAGER desarquiva');
SELECT t.is(public.archive_orders(ARRAY[current_setting('t.arc_delivered')::uuid],true), 1, 'MANAGER arquiva');
SELECT t.login('a0000000-0000-0000-0000-000000000001');
SELECT t.is(public.archive_orders(ARRAY[current_setting('t.arc_delivered')::uuid],false), 1, 'OWNER desarquiva');
SELECT t.ok(t.order_row(current_setting('t.arc_delivered')::uuid)->>'archived_by' IS NULL AND t.order_row(current_setting('t.arc_delivered')::uuid)->>'archived_at' IS NULL, 'desarquivamento limpa metadados');
RESET ROLE;
SELECT t.ok(EXISTS(SELECT 1 FROM public.audit_logs WHERE resource_id=current_setting('t.arc_delivered') AND action='ORDER_UNARCHIVED'), 'auditoria de desarquivamento');
